SELECT
    config.id,
    config.scene_id,
    config.scene_name,
    config.algorithm_code,
    rel.id AS rel_id,
    rel.alarm_type,
    rel.alarm_type_name
FROM sys_scene_config config
INNER JOIN sys_scene_alarm_rel rel ON rel.scene_id = config.scene_id AND rel.delete_flag = 0
WHERE config.delete_flag = 0
AND rel.alarm_type IS NOT NULL
AND rel.alarm_type != ''
AND rel.tenant_id = #{tenantId}
AND rel.industry_code = #{industryCode}

    AND config.app_ver_code = #{appVerCode}
    AND rel.app_ver_code = #{appVerCode}


    AND config.scene_id = #{sceneId}


    AND config.scene_name LIKE CONCAT('%', #{sceneName}, '%')



    AND config.scene_id IN (
        SELECT DISTINCT r.scene_id
        FROM sys_scene_alarm_rel r
        WHERE r.delete_flag = 0
        AND r.alarm_type IS NOT NULL
        AND r.alarm_type != ''
        AND r.tenant_id = #{tenantId}
        AND r.industry_code = #{industryCode}
        AND r.alarm_type IN

            #{item}

    )


    AND rel.alarm_type_name LIKE CONCAT('%', #{alarmTypeName}, '%')


    AND config.algorithm_code = #{algorithmCode}

ORDER BY config.create_time DESC

